import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"SFT（桥接）","description":"监督微调的工程决策桥：何时 prompt 与 RAG 不够、需要用标注数据动权重，以及数据量/成本/延迟/维护四个维度的代价表。","frontmatter":{"title":"SFT（桥接）","description":"监督微调的工程决策桥：何时 prompt 与 RAG 不够、需要用标注数据动权重，以及数据量/成本/延迟/维护四个维度的代价表。","domain":"tech","tags":["tech","training","bridge","sft"],"navOrder":141,"topicId":"model-lifecycle-sft","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/01-model-lifecycle/post-training/sft.md","filePath":"zh/tech/01-model-lifecycle/post-training/sft.md","lastUpdated":1791123720000}'),n={name:"zh/tech/01-model-lifecycle/post-training/sft.md"};function l(i,t,s,d,h,g){return o(),e("div",null,[...t[0]||(t[0]=[a('<blockquote><p><strong>所在组</strong>：模型生命周期（桥接） ｜ <strong>上一组出口</strong>：理解推理基础与接口契约 ｜ <strong>本页出口</strong>：知道何时该动权重而不是改 Prompt 或上检索</p></blockquote><h1 id="sft-桥接" tabindex="-1">SFT（桥接） <a class="header-anchor" href="#sft-桥接" aria-label="Permalink to &quot;SFT（桥接）&quot;">​</a></h1><blockquote><p><strong>桥接页</strong>：本页只回答工程决策问题。训练目标、损失函数与数据配方的推导在 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>（SFT 对应章节）。</p></blockquote><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to &quot;解决什么问题&quot;">​</a></h2><p><strong>监督微调（Supervised Fine-Tuning, SFT）</strong>：拿一个现成的预训练模型，在你的「输入 → 期望输出」标注对上继续训练，让它在特定领域、格式或风格上变专。它改变的是<strong>模型权重</strong>——这与 prompt（每次调用可改、零训练成本）和 RAG（外挂知识库、模型不变）是三条不同的路。</p><p>SFT 擅长的事：</p><ul><li><strong>领域语言</strong>：医疗、法律等术语密集的场景，让模型「说行话」。</li><li><strong>稳定的输出格式</strong>：始终产出同一类 JSON 结构或代码骨架，比 prompt 约束更可靠。</li><li><strong>风格与语气</strong>：品牌写作风格、固定的回答个性。</li><li><strong>用小模型换成本</strong>：把通用大模型的能力蒸馏进一个更小、更快、更便宜的专用模型。</li></ul><p>SFT 不擅长的事（改用主线方案）：</p><ul><li><strong>经常变化的知识</strong>（产品目录、新闻）→ <a href="./../../04-grounding/rag.html">RAG</a>，更新知识库即时生效。</li><li><strong>一次性的格式约束</strong> → <a href="./../../02-inference-interface/structured-output.html">结构化输出</a> + prompt，几分钟生效。</li><li><strong>原型验证阶段</strong> → 任何训练投入在这个阶段都是过早优化。</li></ul><h2 id="何时-prompt-与-rag-不够" tabindex="-1">何时 prompt 与 RAG 不够 <a class="header-anchor" href="#何时-prompt-与-rag-不够" aria-label="Permalink to &quot;何时 prompt 与 RAG 不够&quot;">​</a></h2><p>同时满足以下条件，才把 SFT 提上日程（缺一就回到主线）：</p><ol><li><strong>已穷尽 prompt 与 few-shot</strong>：格式不稳定、风格漂移在提示层修不掉。</li><li><strong>已做过 RAG 优化</strong>：混合检索、重排序、分块调优后，准确性仍不达标，且瓶颈确认在「模型不会这个领域的表达方式」而非「检索不到」。</li><li><strong>有规模可观的高质量标注数据</strong>：需要成百到上万条真实的输入/输出对（经验量级，<strong>未验证</strong>——具体阈值随任务与模型差异极大，以小规模实验为准）。</li><li><strong>有预算与 ML 专业能力</strong>：训练、评估、回归测试是一条持续投入的管线，不是一次性动作。</li></ol><h2 id="决策影响表" tabindex="-1">决策影响表 <a class="header-anchor" href="#决策影响表" aria-label="Permalink to &quot;决策影响表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Prompt</th><th>RAG</th><th>SFT</th></tr></thead><tbody><tr><td><strong>数据量要求</strong></td><td>无（写好提示即可）</td><td>非结构化文档即可</td><td>高质量标注对，规模可观（未验证）</td></tr><tr><td><strong>成本结构</strong></td><td>只有推理费</td><td>推理 + 检索基础设施</td><td>训练算力 + 数据标注 + 评估管线（厂商报价为准，本仓不引用具体数字）</td></tr><tr><td><strong>生效延迟</strong></td><td>即时</td><td>即时（更新索引）</td><td>需重新训练才能更新</td></tr><tr><td><strong>推理延迟</strong></td><td>不变</td><td>增加检索开销</td><td>训练后无检索开销；可用更小模型降低延迟</td></tr><tr><td><strong>维护负担</strong></td><td>低</td><td>中（数据新鲜度）</td><td>高（数据版本、模型版本、回归评估）</td></tr><tr><td><strong>可调试性</strong></td><td>高（直接看 prompt）</td><td>高（看检索命中）</td><td>低（权重不可读，靠评估集说话）</td></tr></tbody></table><h2 id="托管微调服务" tabindex="-1">托管微调服务 <a class="header-anchor" href="#托管微调服务" aria-label="Permalink to &quot;托管微调服务&quot;">​</a></h2><p>如果确认要做 SFT，优先用托管服务而不是自建 GPU 管线：OpenAI Fine-Tuning、Azure OpenAI、Together AI、Anyscale 等均提供微调 API。<strong>注意</strong>：即便用托管服务，数据准备、效果评估、何时停止训练仍需要 ML 判断力；前端/应用工程师的角色是与 ML 工程师协作，通过 API 消费训练产物。</p><h2 id="升级自检清单" tabindex="-1">升级自检清单 <a class="header-anchor" href="#升级自检清单" aria-label="Permalink to &quot;升级自检清单&quot;">​</a></h2><p>向上提交「要做 SFT」之前，逐条打勾；任何一条打不上，先回对应层解决：</p><ul><li>[ ] 输出格式问题已尝试 schema 校验 + few-shot（层 1 <a href="./../../02-inference-interface/structured-output.html">结构化输出</a>）</li><li>[ ] 知识问题已做混合检索 + 重排序 + 分块调优（层 3 <a href="./../../04-grounding/advanced-retrieval.html">高级检索</a>）</li><li>[ ] 已换过至少两三家模型对比，排除「选错模型」这个更便宜的解释（层 5 <a href="./../../08-production/cost-performance.html">成本与性能</a>）</li><li>[ ] 标注数据真实存在且质量可检——不是「理论上可以让人标」</li><li>[ ] 有效果兜底方案：训练后效果变差的回滚路径（回到 prompt + RAG 版本）</li><li>[ ] 有 ML 工程师或托管服务承接训练与评估，不是前端工程师自学试错</li></ul><h2 id="常见反模式" tabindex="-1">常见反模式 <a class="header-anchor" href="#常见反模式" aria-label="Permalink to &quot;常见反模式&quot;">​</a></h2><ul><li><strong>「先微调一下看看」</strong>：把最贵的手段当实验手段。正确顺序是便宜的先试——每个上层手段的调试成本都比下层低一个量级。</li><li><strong>用 SFT 追知识</strong>：把产品目录、FAQ 灌进训练集。知识一变就得重训；这是 RAG 的经典场景。</li><li><strong>只看体感不看评估</strong>：训练后「感觉更顺」不构成证据。上线前后的对比必须走评估集（<a href="./../../08-production/evaluation.html">评估（桥接）</a>）。</li><li><strong>数据靠生成凑数</strong>：用模型生成再自己训练，容易放大模型已有偏差；人工校验环节不能省。</li></ul><h2 id="深层推导与实现" tabindex="-1">深层推导与实现 <a class="header-anchor" href="#深层推导与实现" aria-label="Permalink to &quot;深层推导与实现&quot;">​</a></h2><ul><li>训练目标、数据配方、超参数选择 → <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 的 SFT 章节。</li><li>本仓主线相关的下一步：先回到 <a href="./../../04-grounding/rag.html">RAG</a> 与 <a href="./../../08-production/evaluation.html">评估（桥接）</a>——「SFT 效果更好」必须由评估证据支撑，而不是体感。</li></ul>',23)])])}const b=r(n,[["render",l]]);export{f as __pageData,b as default};
